import{_ as e,o as s,c as t,a2 as n}from"./chunks/framework.C2TvIV46.js";const g=JSON.parse('{"title":"Megalo Headaches","description":"","frontmatter":{},"headers":[],"relativePath":"language/megalo-headaches.md","filePath":"language/megalo-headaches.md"}'),o={name:"language/megalo-headaches.md"};function l(c,a,p,d,r,i){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="megalo-headaches" tabindex="-1">Megalo Headaches <a class="header-anchor" href="#megalo-headaches" aria-label="Permalink to &quot;Megalo Headaches&quot;">​</a></h1><p>These are oddities in Megalo causing unexpected behaviour which you may encounter when authoring gametypes.</p><h2 id="_1-broken-variable-shadowing" tabindex="-1">1. Broken Variable Shadowing <a class="header-anchor" href="#_1-broken-variable-shadowing" aria-label="Permalink to &quot;1. Broken Variable Shadowing&quot;">​</a></h2><p>MegaloEdit allows you to define variables with duplicate names, but some variable types ALWAYS reference the first declared, meaning later declarations are silently impossible to reference and waste space in your gametype.</p><h3 id="affected-first-declaration-wins" tabindex="-1">Affected (first declaration wins) <a class="header-anchor" href="#affected-first-declaration-wins" aria-label="Permalink to &quot;Affected (first declaration wins)&quot;">​</a></h3><p>Redeclaring the same name keeps the <strong>first</strong> declaration for name lookup. Later declarations still take a slot but are ignored when resolving references.</p><p><strong>Variables</strong></p><table tabindex="0"><thead><tr><th>Scope</th><th>Types</th></tr></thead><tbody><tr><td><code>variables global</code></td><td><code>timer</code> only</td></tr><tr><td><code>variables player</code></td><td><code>number</code>, <code>timer</code>, <code>object</code>, <code>player</code>, <code>team</code></td></tr><tr><td><code>variables team</code></td><td><code>number</code>, <code>timer</code>, <code>object</code>, <code>player</code>, <code>team</code></td></tr><tr><td><code>variables object</code></td><td><code>number</code>, <code>timer</code>, <code>object</code>, <code>player</code>, <code>team</code></td></tr></tbody></table><p><strong>Named declarations</strong> (same append + <code>FindIndex</code> pattern)</p><table tabindex="0"><thead><tr><th>Element</th><th>Names</th></tr></thead><tbody><tr><td><code>map_object</code></td><td>filter name</td></tr><tr><td><code>game_options</code></td><td><code>option</code> / <code>ranged_option</code> name</td></tr><tr><td><code>game_options</code></td><td><code>player_traits</code> recipient name</td></tr><tr><td><code>game_stats</code></td><td>stat name</td></tr><tr><td><code>hud_widgets</code></td><td>widget name</td></tr><tr><td><code>loadout</code></td><td>loadout name</td></tr><tr><td><code>loadout_palette</code></td><td>palette name</td></tr><tr><td><code>requisition_palette</code></td><td>palette name</td></tr></tbody></table><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-keyword">global</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">timer</span><span class="megalo-text"> </span><span class="megalo-variable">shared_timer</span><span class="megalo-text"> </span><span class="megalo-number">5</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">timer</span><span class="megalo-text"> </span><span class="megalo-variable">shared_timer</span><span class="megalo-text"> </span><span class="megalo-number">99</span><span class="megalo-text">   </span><span class="megalo-comment">; slot taken, but name still means the first</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-type">player</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">flag</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">flag</span><span class="megalo-text"> </span><span class="megalo-number">1</span><span class="megalo-text">               </span><span class="megalo-comment">; same: first \`flag\` wins</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">map_object</span><span class="megalo-text"> </span><span class="megalo-variable">shared_filter</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">label</span><span class="megalo-text"> </span><span class="megalo-string">&quot;first&quot;</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-keyword">map_object</span><span class="megalo-text"> </span><span class="megalo-variable">shared_filter</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">label</span><span class="megalo-text"> </span><span class="megalo-string">&quot;second&quot;</span><span class="megalo-text">                    </span><span class="megalo-comment">; slot taken; references resolve to the first</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h3 id="not-affected-last-declaration-wins" tabindex="-1">Not affected (last declaration wins) <a class="header-anchor" href="#not-affected-last-declaration-wins" aria-label="Permalink to &quot;Not affected (last declaration wins)&quot;">​</a></h3><p>These use <code>FindLastIndex</code>, so a later declaration with the same name correctly shadows the earlier one for name lookup (both still consume slots).</p><table tabindex="0"><thead><tr><th>Scope</th><th>Types</th></tr></thead><tbody><tr><td><code>variables global</code></td><td><code>number</code>, <code>object</code>, <code>player</code>, <code>team</code></td></tr><tr><td>temporary variables</td><td>all types (<code>temporary</code> in a trigger)</td></tr></tbody></table><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-keyword">global</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">counter</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">counter</span><span class="megalo-text"> </span><span class="megalo-number">7</span><span class="megalo-text">            </span><span class="megalo-comment">; references resolve to this one</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>Strings are a different case: MegaloEdit <strong>errors</strong> on a duplicate string name in the same language rather than shadowing.</p><h2 id="_2-inaccessible-target-team" tabindex="-1">2. Inaccessible <code>target_team</code> <a class="header-anchor" href="#_2-inaccessible-target-team" aria-label="Permalink to &quot;2. Inaccessible \`target_team\`&quot;">​</a></h2><p>The engine exposes an explicit team slot for the team that owns <a href="/MegaloEvolved/beta/docs/language/references#context-references"><code>target_player</code></a> (<code>ExplicitTeam.TargetTeam</code> on the wire). MegaloEdit’s autocomplete even lists <code>target_team</code>, but its team parser only accepts <code>local_team</code> for the HUD local-player owner team — it never matches <code>target_team</code> (or the older alias <code>hud_target_player_owner_team</code>).</p><p>So in MegaloEdit you cannot write:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action set some_team set_to target_team</span></span></code></pre></div><p>The reference is a dead keyword: present in autocomplete and in the binary encoding, absent from parse.</p><h2 id="_3-inaccessible-coop-spawning-navpoint-icon" tabindex="-1">3. Inaccessible <code>coop spawning</code> navpoint icon <a class="header-anchor" href="#_3-inaccessible-coop-spawning-navpoint-icon" aria-label="Permalink to &quot;3. Inaccessible \`coop spawning\` navpoint icon&quot;">​</a></h2><p><code>navpoint_set_icon</code>’s name table includes a final entry whose string is literally <strong><code>coop spawning</code></strong> (with a space).</p><p>MegaloEdit resolves icon names with <code>read_enumerated_string</code>, which consumes <strong>one</strong> identifier token and compares it to each table string. A single token can never equal <code>&quot;coop spawning&quot;</code>, so the icon is impossible to write:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action navpoint_set_icon marker coop spawning   </span><span class="megalo-comment">; never matches</span></span></code></pre></div>`,25)])])}const h=e(o,[["render",l]]);export{g as __pageData,h as default};
